@extends('layouts.app')
@section('title','Free Online Tools: Image, File & Developer Utilities | MRK Digital')
@section('description','Use free online image compressor, image converter, ZIP extractor, text-to-image, OCR and developer tools. Fast browser-based utilities with direct links and privacy-friendly processing.')
@section('content')
<main class="section tools-page"><div class="container">
  <div class="section-heading">
    <span class="eyebrow">MRK DIGITAL TOOLKIT</span>
    <h1>Free Online Tools</h1>
    <p>Free browser-based tools for images, files, text, video information and web development. Choose a category or search for a tool. Where supported, files are processed on your device.</p>
  </div>
  <label for="tool-search"><strong>Find a tool</strong></label>
  <input id="tool-search" type="search" placeholder="Search image compressor, JSON, ZIP..." style="width:100%;padding:.85rem;margin:.5rem 0 1rem">
  <div class="tool-actions" role="group" aria-label="Tool categories" style="display:flex;gap:.5rem;flex-wrap:wrap;margin-bottom:1.5rem">
    <button class="button primary" data-filter="all" type="button">All Tools</button><button class="button secondary" data-filter="image" type="button">Image Tools</button><button class="button secondary" data-filter="file" type="button">File & OCR</button><button class="button secondary" data-filter="video" type="button">Video & Audio</button><button class="button secondary" data-filter="developer" type="button">Developer Tools</button><button class="button secondary" data-filter="text" type="button">Text & Everyday</button>
  </div>
  <div class="cards tools-grid" id="all-tools">
    <article class="tool-card" data-category="image" id="image-compressor"><h2>Image Compressor</h2><p>Compress JPG, PNG or WebP images in your browser and download a smaller file.</p><label for="img-compress-file">Choose image</label><input id="img-compress-file" type="file" accept="image/*"><label for="img-quality">Quality <span id="img-quality-value">75%</span></label><input id="img-quality" type="range" min="10" max="95" value="75"><button class="button primary" id="img-compress-btn" type="button">Compress & Download</button><p id="img-compress-status" aria-live="polite"></p></article>
    <article class="tool-card" data-category="image" id="image-converter"><h2>Image Converter</h2><p>Convert an image to JPG, PNG or WebP without uploading it to a server.</p><input id="img-convert-file" type="file" accept="image/*"><select id="img-format" aria-label="Output image format"><option value="image/webp">WebP</option><option value="image/jpeg">JPG</option><option value="image/png">PNG</option></select><button class="button primary" id="img-convert-btn" type="button">Convert & Download</button><p id="img-convert-status" aria-live="polite"></p></article>
    <article class="tool-card" data-category="image" id="image-resizer"><h2>Image Resizer</h2><p>Resize an image to custom pixel dimensions.</p><input id="resize-file" type="file" accept="image/*"><div class="tool-actions"><input id="resize-width" type="number" min="1" max="10000" placeholder="Width px" aria-label="Width in pixels"><input id="resize-height" type="number" min="1" max="10000" placeholder="Height px" aria-label="Height in pixels"></div><button class="button primary" id="resize-btn" type="button">Resize & Download</button><p id="resize-status" aria-live="polite"></p></article>
    <article class="tool-card" data-category="image" id="text-to-image"><h2>Text to Image (SVG)</h2><p>Create a downloadable image card from your text. Works offline in the browser.</p><textarea id="tti-text" rows="3" placeholder="Write text for your image"></textarea><input id="tti-bg" type="color" value="#082b5b" aria-label="Background color"><input id="tti-fg" type="color" value="#ffffff" aria-label="Text color"><button class="button primary" id="tti-btn" type="button">Create SVG Image</button></article>
    <article class="tool-card" data-category="image" id="image-base64"><h2>Image to Base64</h2><p>Convert an image file into a Base64 data URL for testing and development.</p><input id="base64-image-file" type="file" accept="image/*"><button class="button primary" id="base64-image-btn" type="button">Convert</button><textarea id="base64-image-output" rows="3" readonly placeholder="Base64 output"></textarea><button class="button secondary" data-copy="base64-image-output" type="button">Copy result</button></article>
    <article class="tool-card" data-category="file" id="zip-extractor"><h2>ZIP File Extractor</h2><p>List and download files from a ZIP archive. Uses JSZip from a public CDN; requires an internet connection.</p><input id="zip-file" type="file" accept=".zip,application/zip"><button class="button primary" id="zip-btn" type="button">Open ZIP</button><div id="zip-results" aria-live="polite"></div><small>Only open archives from sources you trust.</small></article>
    <article class="tool-card" data-category="file" id="image-ocr"><h2>Image to Text (OCR)</h2><p>Extract readable text from an image using browser OCR. The OCR engine loads from a CDN when used.</p><input id="ocr-file" type="file" accept="image/*"><button class="button primary" id="ocr-btn" type="button">Extract Text</button><textarea id="ocr-output" rows="5" readonly placeholder="Recognized text will appear here"></textarea><small>Accuracy depends on image quality and language support.</small></article>
    <article class="tool-card" data-category="file" id="file-info"><h2>File Size & Type Checker</h2><p>Check a local file's name, size, MIME type and last modified date.</p><input id="file-info-input" type="file"><pre id="file-info-output" aria-live="polite"></pre></article>
    <article class="tool-card" data-category="video" id="video-info"><h2>Video Information Checker</h2><p>Read local video's duration, dimensions and file size without uploading it.</p><input id="video-file" type="file" accept="video/*"><video id="video-preview" controls style="width:100%;max-height:180px;display:none"></video><pre id="video-info-output" aria-live="polite"></pre></article>
    <article class="tool-card" data-category="video" id="audio-info"><h2>Audio Information Checker</h2><p>Check local audio duration and file size.</p><input id="audio-file" type="file" accept="audio/*"><audio id="audio-preview" controls style="width:100%;display:none"></audio><pre id="audio-info-output" aria-live="polite"></pre></article>
    <article class="tool-card" data-category="video" id="video-to-mp3"><h2>Video to MP3 — Requirements</h2><p>Reliable video-to-MP3 conversion needs a media codec engine. This lightweight free-hosting build does not bundle FFmpeg yet, so it will not pretend to convert files. Use the video information checker for now.</p><a href="#video-info">Open Video Information Checker</a></article>
    <article class="tool-card" data-category="developer" id="json-formatter"><h2>JSON Formatter & Validator</h2><p>Format JSON and identify syntax errors locally.</p><textarea id="json-input" rows="3" placeholder='{"name":"MRK"}'></textarea><button class="button primary" id="json-btn" type="button">Format JSON</button><textarea id="json-output" rows="4" readonly></textarea></article>
    <article class="tool-card" data-category="developer" id="base64-tool"><h2>Base64 Encoder / Decoder</h2><textarea id="b64-input" rows="3" placeholder="Enter text or Base64"></textarea><div class="tool-actions"><button class="button primary" id="b64-encode" type="button">Encode</button><button class="button secondary" id="b64-decode" type="button">Decode</button></div><textarea id="b64-output" rows="3" readonly></textarea></article>
    <article class="tool-card" data-category="developer" id="url-encoder"><h2>URL Encoder / Decoder</h2><textarea id="url-input" rows="2" placeholder="Text or encoded URL"></textarea><div class="tool-actions"><button class="button primary" id="url-encode" type="button">Encode</button><button class="button secondary" id="url-decode" type="button">Decode</button></div><textarea id="url-output" rows="2" readonly></textarea></article>
    <article class="tool-card" data-category="developer" id="html-escaper"><h2>HTML Entity Escaper</h2><textarea id="html-input" rows="2" placeholder="<h1>Hello</h1>"></textarea><button class="button primary" id="html-btn" type="button">Escape HTML</button><textarea id="html-output" rows="2" readonly></textarea></article>
    <article class="tool-card" data-category="developer" id="uuid-generator"><h2>UUID Generator</h2><p id="uuid-output">Generate a random UUID.</p><button class="button primary" id="uuid-btn" type="button">Generate UUID</button></article>
    <article class="tool-card" data-category="developer" id="timestamp-converter"><h2>Unix Timestamp Converter</h2><input id="timestamp-input" type="number" placeholder="Timestamp in seconds"><button class="button primary" id="timestamp-btn" type="button">Convert</button><p id="timestamp-output" aria-live="polite"></p><button class="button secondary" id="timestamp-now" type="button">Use current timestamp</button></article>
    <article class="tool-card" data-category="developer" id="regex-tester"><h2>Regex Tester</h2><input id="regex-pattern" placeholder="Regular expression"><textarea id="regex-text" rows="2" placeholder="Test text"></textarea><button class="button primary" id="regex-btn" type="button">Find Matches</button><pre id="regex-output"></pre></article>
    <article class="tool-card" data-category="developer" id="color-converter"><h2>HEX / RGB Color Converter</h2><input id="color-input" type="color" value="#087ea4"><p id="color-output">#087ea4</p></article>
    <article class="tool-card" data-category="developer" id="gradient-generator"><h2>CSS Gradient Generator</h2><input id="gradient-a" type="color" value="#082b5b" aria-label="First gradient color"><input id="gradient-b" type="color" value="#12b8a6" aria-label="Second gradient color"><input id="gradient-angle" type="range" min="0" max="360" value="135" aria-label="Gradient angle"><div id="gradient-preview" style="height:70px;border-radius:8px;margin:.5rem 0"></div><textarea id="gradient-output" rows="2" readonly></textarea><button class="button primary" id="gradient-btn" type="button">Generate CSS</button></article>
    <article class="tool-card" data-category="developer" id="css-minifier"><h2>CSS Minifier</h2><textarea id="css-input" rows="3" placeholder="Paste CSS"></textarea><button class="button primary" id="css-btn" type="button">Minify CSS</button><textarea id="css-output" rows="3" readonly></textarea></article>
    <article class="tool-card" data-category="developer" id="jwt-decoder"><h2>JWT Payload Decoder</h2><p>Decodes the payload only; it does not verify the signature.</p><textarea id="jwt-input" rows="2" placeholder="Paste JWT"></textarea><button class="button primary" id="jwt-btn" type="button">Decode Payload</button><pre id="jwt-output"></pre></article>
    <article class="tool-card" data-category="developer" id="query-parser"><h2>Query String Parser</h2><input id="query-input" placeholder="?name=MRK&role=developer"><button class="button primary" id="query-btn" type="button">Parse Query</button><pre id="query-output"></pre></article>
    <article class="tool-card" data-category="developer" id="number-base"><h2>Number Base Converter</h2><input id="number-input" value="255"><select id="number-base"><option value="10">Decimal</option><option value="2">Binary</option><option value="8">Octal</option><option value="16">Hexadecimal</option></select><button class="button primary" id="number-btn" type="button">Convert</button><pre id="number-output"></pre></article>
    <article class="tool-card" data-category="developer" id="html-preview"><h2>Sandboxed HTML Preview</h2><textarea id="snippet-input" rows="3" placeholder="<h2>Hello!</h2>"></textarea><button class="button primary" id="snippet-btn" type="button">Preview HTML</button><iframe id="snippet-preview" sandbox="" title="Sandboxed HTML preview" style="width:100%;height:150px;background:white"></iframe><small>Scripts are disabled by sandboxing.</small></article>
    <article class="tool-card" data-category="text" id="word-counter"><h2>Word & Character Counter</h2><textarea id="word-input" rows="3" placeholder="Type or paste text"></textarea><p id="word-output" aria-live="polite">0 words · 0 characters</p></article>
    <article class="tool-card" data-category="text" id="case-converter"><h2>Text Case Converter</h2><textarea id="case-input" rows="2" placeholder="Enter text"></textarea><div class="tool-actions"><button class="button secondary" data-case="upper" type="button">UPPERCASE</button><button class="button secondary" data-case="lower" type="button">lowercase</button><button class="button secondary" data-case="title" type="button">Title Case</button></div><p id="case-output"></p></article>
    <article class="tool-card" data-category="text" id="slug-generator"><h2>URL Slug Generator</h2><input id="slug-input" placeholder="My New Blog Post"><p id="slug-output" aria-live="polite"></p></article>
    <article class="tool-card" data-category="text" id="password-generator"><h2>Password Generator</h2><label for="password-length">Length (8–48)</label><input id="password-length" type="number" min="8" max="48" value="16"><button class="button primary" id="password-btn" type="button">Generate Password</button><p id="password-output" style="overflow-wrap:anywhere"></p></article>
    <article class="tool-card" data-category="text" id="percentage-calculator"><h2>Percentage Calculator</h2><input id="percent-rate" type="number" placeholder="Percent"><input id="percent-value" type="number" placeholder="Of number"><button class="button primary" id="percent-btn" type="button">Calculate</button><p id="percent-output"></p></article>
    <article class="tool-card" data-category="text" id="discount-calculator"><h2>Discount Calculator</h2><input id="discount-price" type="number" min="0" placeholder="Original price (Rs)"><input id="discount-rate" type="number" min="0" max="100" placeholder="Discount %"><button class="button primary" id="discount-btn" type="button">Calculate Price</button><p id="discount-output"></p></article>
    <article class="tool-card" data-category="text" id="unit-converter"><h2>Unit Converter</h2><input id="unit-input" type="number" value="1"><select id="unit-choice"><option value="kg">kg → lb</option><option value="lb">lb → kg</option><option value="km">km → miles</option><option value="mi">miles → km</option><option value="c">°C → °F</option><option value="f">°F → °C</option></select><p id="unit-output"></p></article>
  </div>
  <section style="margin-top:2rem"><h2>How to use MRK Free Online Tools</h2><p>Choose a category, search by tool name, open the tool and follow its instructions. Downloadable image and file utilities work locally when supported. Do not upload confidential files to websites you do not trust.</p><h2>Frequently asked questions</h2><h3>Are these tools free?</h3><p>Yes, the listed utilities are free to use without creating an account.</p><h3>Are my files uploaded?</h3><p>Image conversion and resizing use your browser. Some optional features load code from public CDNs; check the note on each tool before using it with sensitive data.</p><h3>Why is a video-to-MP3 converter not available yet?</h3><p>Video transcoding requires a media codec engine. This version clearly identifies that limitation rather than offering a non-working conversion button.</p></section>
  <p style="margin-top:1.5rem;color:var(--muted,#64748b)">MRK Digital tools are provided as a convenience. Verify important outputs before relying on them. Financial and tax calculations are estimates only.</p>
</div></main>
<script>
(function(){
 const $=id=>document.getElementById(id), set=(id,v)=>{if($(id))$(id).textContent=v}, val=id=>$(id).value;
 const fmt=n=>Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:3}):'—';
 const download=(blob,name)=>{const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)};
 const loadImage=file=>new Promise((resolve,reject)=>{const img=new Image(),u=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(u);resolve(img)};img.onerror=()=>{URL.revokeObjectURL(u);reject(Error('Could not read image'))};img.src=u});
 const canvasBlob=(canvas,type,quality)=>new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('This image format is not supported by the browser')),type,quality));
 $('tool-search').addEventListener('input',filterTools);
 let activeFilter='all';
 function filterTools(){const q=val('tool-search').toLowerCase();document.querySelectorAll('#all-tools .tool-card').forEach(card=>{card.hidden=!(activeFilter==='all'||card.dataset.category===activeFilter)&&true;const match=(card.innerText+' '+card.id).toLowerCase().includes(q);card.hidden=card.hidden||!match})}
 document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{activeFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.className='button '+(x===b?'primary':'secondary')});filterTools()}));
 $('img-quality').addEventListener('input',()=>set('img-quality-value',val('img-quality')+'%'));
 $('img-compress-btn').addEventListener('click',async()=>{try{const f=$('img-compress-file').files[0];if(!f)throw Error('Choose an image first.');const im=await loadImage(f),c=document.createElement('canvas');c.width=im.naturalWidth;c.height=im.naturalHeight;c.getContext('2d').drawImage(im,0,0);const type=f.type==='image/png'?'image/png':'image/jpeg',blob=await canvasBlob(c,type,Number(val('img-quality'))/100);download(blob,'compressed-'+f.name.replace(/\.[^.]+$/,'')+(type==='image/png'?'.png':'.jpg'));set('img-compress-status','Original '+fmt(f.size/1024)+' KB · Output '+fmt(blob.size/1024)+' KB')}catch(e){set('img-compress-status',e.message)}});
 $('img-convert-btn').addEventListener('click',async()=>{try{const f=$('img-convert-file').files[0];if(!f)throw Error('Choose an image first.');const im=await loadImage(f),c=document.createElement('canvas');c.width=im.naturalWidth;c.height=im.naturalHeight;c.getContext('2d').drawImage(im,0,0);const type=val('img-format'),blob=await canvasBlob(c,type,.9),ext=type==='image/jpeg'?'jpg':type.split('/')[1];download(blob,'converted-image.'+ext);set('img-convert-status','Converted successfully: '+fmt(blob.size/1024)+' KB')}catch(e){set('img-convert-status',e.message)}});
 $('resize-btn').addEventListener('click',async()=>{try{const f=$('resize-file').files[0],w=Number(val('resize-width')),h=Number(val('resize-height'));if(!f||!w||!h||w>10000||h>10000)throw Error('Choose an image and valid dimensions (1–10000).');const im=await loadImage(f),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);const b=await canvasBlob(c,'image/png');download(b,'resized-image.png');set('resize-status','Ready: '+w+' × '+h+' px')}catch(e){set('resize-status',e.message)}});
 $('tti-btn').addEventListener('click',()=>{const esc=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');const lines=val('tti-text').split('\n').slice(0,8);const svg='<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630"><rect width="100%" height="100%" fill="'+val('tti-bg')+'"/><text x="600" y="'+(315-(lines.length-1)*30)+'" fill="'+val('tti-fg')+'" font-family="Arial,sans-serif" font-size="44" text-anchor="middle">'+lines.map((l,i)=>'<tspan x="600" dy="'+(i?60:0)+'">'+esc(l)+'</tspan>').join('')+'</text></svg>';download(new Blob([svg],{type:'image/svg+xml'}),'mrk-text-image.svg')});
 $('base64-image-btn').addEventListener('click',()=>{const f=$('base64-image-file').files[0];if(!f)return set('base64-image-output','Choose an image first.');const r=new FileReader();r.onload=()=> $('base64-image-output').value=r.result;r.readAsDataURL(f)});
 document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(val(b.dataset.copy));b.textContent='Copied'}catch(e){$(b.dataset.copy).select();set('base64-image-output','Select and copy the text manually.')}}));
 $('zip-btn').addEventListener('click',async()=>{const f=$('zip-file').files[0];if(!f)return set('zip-results','Choose a ZIP file first.');set('zip-results','Loading ZIP engine…');try{if(!window.JSZip){await new Promise((res,rej)=>{const s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';s.onload=res;s.onerror=()=>rej(Error('Could not load ZIP engine. Check your internet connection.'));document.head.appendChild(s)})}const z=await JSZip.loadAsync(f),box=$('zip-results');box.replaceChildren();Object.keys(z.files).forEach(name=>{const item=z.files[name];const row=document.createElement('p');if(item.dir){row.textContent='📁 '+name}else{const a=document.createElement('a');a.href='#';a.textContent='Download '+name;a.addEventListener('click',async e=>{e.preventDefault();download(await item.async('blob'),name.split('/').pop()||'extracted-file')});row.appendChild(a)}box.appendChild(row)});if(!box.children.length)box.textContent='No files found.'}catch(e){set('zip-results','Could not open ZIP: '+e.message)}});
 $('ocr-btn').addEventListener('click',async()=>{const f=$('ocr-file').files[0];if(!f)return set('ocr-output','Choose an image first.');$('ocr-output').value='Loading OCR engine; please wait…';try{if(!window.Tesseract){await new Promise((res,rej)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';s.onload=res;s.onerror=()=>rej(Error('Could not load OCR engine. Check internet connection.'));document.head.appendChild(s)})}const result=await Tesseract.recognize(f,'eng');$('ocr-output').value=result.data.text||'No text recognized.'}catch(e){$('ocr-output').value=e.message}});
 $('file-info-input').addEventListener('change',()=>{const f=$('file-info-input').files[0];set('file-info-output',f?JSON.stringify({name:f.name,sizeBytes:f.size,sizeKB:fmt(f.size/1024),type:f.type||'Unknown',lastModified:new Date(f.lastModified).toISOString()},null,2):'')});
 function mediaInfo(input,preview,output){$(input).addEventListener('change',()=>{const f=$(input).files[0];if(!f)return;const p=$(preview);p.src=URL.createObjectURL(f);p.style.display='block';p.onloadedmetadata=()=>set(output,JSON.stringify({name:f.name,sizeMB:fmt(f.size/1048576),durationSeconds:fmt(p.duration),width:p.videoWidth||undefined,height:p.videoHeight||undefined,type:f.type},null,2))})}
 mediaInfo('video-file','video-preview','video-info-output');mediaInfo('audio-file','audio-preview','audio-info-output');
 $('json-btn').addEventListener('click',()=>{try{$('json-output').value=JSON.stringify(JSON.parse(val('json-input')),null,2)}catch(e){$('json-output').value='Invalid JSON: '+e.message}});
 $('b64-encode').addEventListener('click',()=>{try{$('b64-output').value=btoa(unescape(encodeURIComponent(val('b64-input'))))}catch(e){$('b64-output').value=e.message}});$('b64-decode').addEventListener('click',()=>{try{$('b64-output').value=decodeURIComponent(escape(atob(val('b64-input'))))}catch(e){$('b64-output').value='Invalid Base64'}});
 $('url-encode').addEventListener('click',()=> $('url-output').value=encodeURIComponent(val('url-input')));$('url-decode').addEventListener('click',()=>{try{$('url-output').value=decodeURIComponent(val('url-input'))}catch(e){$('url-output').value='Invalid encoding'}});
 $('html-btn').addEventListener('click',()=>{$('html-output').value=val('html-input').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')});
 $('uuid-btn').addEventListener('click',()=>set('uuid-output',crypto.randomUUID?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})));
 $('timestamp-btn').addEventListener('click',()=>{const n=Number(val('timestamp-input')),d=new Date(n*1000);set('timestamp-output',Number.isFinite(n)&&Number.isFinite(d.getTime())?d.toISOString():'Enter valid seconds timestamp')});$('timestamp-now').addEventListener('click',()=>{$('timestamp-input').value=Math.floor(Date.now()/1000);$('timestamp-btn').click()});
 $('regex-btn').addEventListener('click',()=>{try{const r=new RegExp(val('regex-pattern'),'g'),m=val('regex-text').match(r)||[];set('regex-output',m.length?m.join('\n'):'No matches')}catch(e){set('regex-output',e.message)}});
 function colorUpdate(){const hex=val('color-input'),n=parseInt(hex.slice(1),16);set('color-output',hex.toUpperCase()+' — RGB('+ (n>>16)+', '+(n>>8&255)+', '+(n&255)+')')}$('color-input').addEventListener('input',colorUpdate);
 function gradient(){const s='linear-gradient('+val('gradient-angle')+'deg, '+val('gradient-a')+', '+val('gradient-b')+')';$('gradient-preview').style.background=s;$('gradient-output').value='background: '+s+';'}['gradient-a','gradient-b','gradient-angle'].forEach(id=>$(id).addEventListener('input',gradient));$('gradient-btn').addEventListener('click',gradient);
 $('css-btn').addEventListener('click',()=> $('css-output').value=val('css-input').replace(/\/\*[\s\S]*?\*\//g,'').replace(/\s+/g,' ').replace(/\s*([{}:;,])\s*/g,'$1').trim());
 $('jwt-btn').addEventListener('click',()=>{try{const p=val('jwt-input').split('.')[1].replace(/-/g,'+').replace(/_/g,'/');set('jwt-output',JSON.stringify(JSON.parse(decodeURIComponent(escape(atob(p)))),null,2))}catch(e){set('jwt-output','Invalid JWT payload. Signature is not verified.')}});
 $('query-btn').addEventListener('click',()=>{try{set('query-output',JSON.stringify(Object.fromEntries(new URLSearchParams(val('query-input').replace(/^\?/,''))),null,2))}catch(e){set('query-output',e.message)}});
 $('number-btn').addEventListener('click',()=>{const n=parseInt(val('number-input'),Number(val('number-base')));set('number-output',Number.isNaN(n)?'Invalid number':'Binary: '+n.toString(2)+'\nOctal: '+n.toString(8)+'\nDecimal: '+n+'\nHex: '+n.toString(16))});
 $('snippet-btn').addEventListener('click',()=>{$('snippet-preview').srcdoc=val('snippet-input').replace(/<script\b[\s\S]*?<\/script\s*>/gi,'').replace(/\son\w+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi,'')});
 $('word-input').addEventListener('input',()=>{const t=val('word-input'),trim=t.trim();set('word-output',(trim?trim.split(/\s+/).length:0)+' words · '+t.length+' characters · '+t.replace(/\s/g,'').length+' without spaces')});
 document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>{const t=val('case-input');set('case-output',b.dataset.case==='upper'?t.toUpperCase():b.dataset.case==='lower'?t.toLowerCase():t.toLowerCase().replace(/\b\w/g,c=>c.toUpperCase()))}));
 $('slug-input').addEventListener('input',()=>set('slug-output',val('slug-input').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')));
 $('password-btn').addEventListener('click',()=>{const n=Math.max(8,Math.min(48,Number(val('password-length'))||16)),chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%^&*()-_=+';let out='';const a=new Uint32Array(n);crypto.getRandomValues(a);for(const x of a)out+=chars[x%chars.length];set('password-output',out)});
 $('percent-btn').addEventListener('click',()=>set('percent-output','Result: '+fmt(Number(val('percent-rate'))*Number(val('percent-value'))/100)));
 $('discount-btn').addEventListener('click',()=>{const p=Number(val('discount-price')),r=Number(val('discount-rate'));set('discount-output',p>=0&&r>=0&&r<=100?'Save Rs '+fmt(p*r/100)+' · Pay Rs '+fmt(p*(1-r/100)):'Enter a valid price and discount from 0–100%.')});
 function unit(){const v=Number(val('unit-input')),t=val('unit-choice'),fn={kg:n=>n*2.2046226218,lb:n=>n/2.2046226218,km:n=>n*.6213711922,mi:n=>n/.6213711922,c:n=>n*9/5+32,f:n=>(n-32)*5/9}[t],u={kg:'lb',lb:'kg',km:'miles',mi:'km',c:'°F',f:'°C'}[t];set('unit-output',fmt(v)+' → '+fmt(fn(v))+' '+u)}$('unit-input').addEventListener('input',unit);$('unit-choice').addEventListener('change',unit);
 colorUpdate();gradient();unit();filterTools();
})();
</script>
@endsection